package com.yonlab.vision;
import java.io.*;import java.util.concurrent.atomic.AtomicBoolean;import org.junit.Test;import static org.junit.Assert.*;
public class SignageImportPolicyTest {
 @Test public void onlyOwnedImmutableFileNamesMapToPrivatePaths()throws Exception{String name="private:signage/imports/12345678-abcd-0123-4567-123456789abc.img";assertTrue(SignageImportPolicy.privateUri(name));assertEquals("signage/imports/12345678-abcd-0123-4567-123456789abc.img",SignageImportPolicy.relativePath(name));assertFalse(SignageImportPolicy.privateUri("private:signage/imports/../../source.img"));assertFalse(SignageImportPolicy.privateUri("file:///sdcard/a.jpg"));assertFalse(SignageImportPolicy.privateUri("private:signage/imports/%2e%2e/a.img"));}
 @Test public void copiedBytesAreExactAndIndependentOfLaterSourceMutation()throws Exception{byte[] input={0,1,2,3,(byte)255};ByteArrayOutputStream out=new ByteArrayOutputStream();assertEquals(5,SignageImportPolicy.copy(new ByteArrayInputStream(input),out,5,()->false));input[0]=99;assertArrayEquals(new byte[]{0,1,2,3,(byte)255},out.toByteArray());}
 @Test public void overLimitCannotWritePastBound()throws Exception{ByteArrayOutputStream out=new ByteArrayOutputStream();try{SignageImportPolicy.copy(new ByteArrayInputStream(new byte[12]),out,10,()->false);fail();}catch(IOException expected){assertTrue(out.size()<=10);}}
 @Test public void cancellationStopsBeforeNextChunk()throws Exception{AtomicBoolean canceled=new AtomicBoolean();ByteArrayOutputStream out=new ByteArrayOutputStream();InputStream in=new ByteArrayInputStream(new byte[32000]){public synchronized int read(byte[] b,int o,int n){int count=super.read(b,o,3);canceled.set(true);return count;}};try{SignageImportPolicy.copy(in,out,32000,canceled::get);fail();}catch(IOException expected){assertEquals(3,out.size());}}
 @Test(expected=IOException.class)public void stalledProviderCannotSpinForever()throws Exception{SignageImportPolicy.copy(new InputStream(){public int read(){return 0;}public int read(byte[] b){return 0;}},new ByteArrayOutputStream(),10,()->false);}
}
